from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit
import hashlib
import json
import re

class NoticeLinks(HTMLParser):
    def __init__(self):
        super().__init__()
        self.current = None
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            self.current = [dict(attrs).get('href', ''), []]

    def handle_data(self, data):
        if self.current is not None:
            self.current[1].append(data)

    def handle_endtag(self, tag):
        if tag == 'a' and self.current is not None:
            href, parts = self.current
            self.links.append((href, ' '.join(' '.join(parts).split())))
            self.current = None

root = Path('products/services/contracts-finder-small-data-qa')
source = root / 'raw/targeted-data-cleansing.html'
raw = source.read_bytes()
parser = NoticeLinks()
parser.feed(raw.decode('utf-8', errors='replace'))
base = 'https://www.contractsfinder.service.gov.uk/'
by_url = {}
for href, title in parser.links:
    parsed = urlsplit(urljoin(base, href))
    if parsed.scheme != 'https' or parsed.netloc.lower() != 'www.contractsfinder.service.gov.uk' or not re.match(r'^/notice/[0-9a-f-]{36}/?$', parsed.path, re.I):
        continue
    url = base.rstrip('/') + parsed.path.rstrip('/')
    if len(title) > len(by_url.get(url, '')):
        by_url[url] = title
    else:
        by_url.setdefault(url, title)

priority = re.compile(r'\b(data cleans(?:e|ing)|data quality|data reconciliation|data validation|data migration|data matching|data deduplication|data conversion)\b', re.I)
links = [{'url': url, 'anchor_title': title, 'matched_terms': priority.findall(title)} for url, title in by_url.items()]
links.sort(key=lambda row: -len(row['matched_terms']))
report = {'source_path': str(source), 'source_sha256': hashlib.sha256(raw).hexdigest(), 'original_notice_links': len(links), 'title_matches': sum(bool(row['matched_terms']) for row in links), 'navigation': links, 'scope': 'Anchor text supports navigation only. Verify current deadline, standalone scope, acceptance criteria, supplier eligibility and response route in the original. A title miss does not exclude qualified scope.'}
out = root / 'original-notice-title-triage.json'
out.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(out), 'original_notice_links': len(links), 'title_matches': report['title_matches']}))
